import { Table, GenericColumn, ReferenceColumn, BooleanColumn, StringColumn } from '../../db'
import { UserImageColumn } from '../../db/types/UserImage'

export const sp_theme = Table({
    allowWebServiceAccess: true,
    attributes: {
        update_synch: true,
    },
    display: 'name',
    extends: 'sys_metadata',
    label: 'Theme',
    name: 'sp_theme',
    schema: {
        css_variables: GenericColumn({
            columnType: 'properties',
            label: 'CSS variables',
            maxLength: 16777215,
        }),
        footer: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Footer',
            referenceTable: 'sp_header_footer',
        }),
        header: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Header',
            referenceTable: 'sp_header_footer',
        }),
        navbar_fixed: BooleanColumn({
            default: true,
            label: [
                {
                    hint: "The header 'fixed' to the top of the page",
                    label: 'Fixed header',
                    plural: 'Fixed headers',
                    language: 'en',
                },
            ],
        }),
        footer_fixed: BooleanColumn({
            default: true,
            label: [
                {
                    hint: "The footer 'fixed' to the bottom of the page",
                    label: 'Fixed footer',
                    plural: 'Fixed footers',
                    language: 'en',
                },
            ],
        }),
        turn_off_scss_compilation: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'If selected then SCSS will not be compiled',
                    label: 'Turn off SCSS compilation',
                    plural: 'Turn off SCSS compilations',
                    language: 'en',
                },
            ],
        }),
        matching_now_experience_theme: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'Select the matching next experience theme record. You will be able to map variables from this theme in the portal theme',
                    label: 'Matching Next Experience Theme',
                    plural: 'Matching Next Experience Themes',
                    language: 'en',
                },
            ],
            referenceTable: 'sys_ux_theme',
            referenceQual: 'active=true^EQ',
        }),
        icon: UserImageColumn({
            mandatory: false,
            label: 'Icon',
            read_only: false,
            active: true,
        }),
        logo: UserImageColumn({
            mandatory: false,
            label: 'Logo',
            read_only: false,
            active: true,
        }),
        logo_alt_text: StringColumn({
            label: 'Logo alt text',
            maxLength: 100,
        }),
        sys_id: GenericColumn({
            columnType: 'GUID',
            label: 'Sys ID',
            maxLength: 32,
            primary: true,
        }),
        name: StringColumn({
            label: 'Name',
            maxLength: 100,
        }),
    },
})
